from math import sqrt

def count_distinct_prime_factors(n):
    count = 0
    if n % 2 == 0:
        count += 1
        while n % 2 == 0:
            n //= 2
    for i in range(3, int(sqrt(n)) + 1, 2):
        if n % i == 0:
            count += 1
            while n % i == 0:
                n //= i
    if n > 2:
        count += 1
    return count

def max_revenue(N, S):
