    # Group by the number of distinct prime factors
    groups = defaultdict(list)
    for i, pf_count in enumerate(prime_factors_count):
        groups[pf_count].append(i)

    # Calculate the maximum revenue
    max_rev = 0
    for group in groups.values():
        max_rev += len(group)

    return max_rev

